class Solution {
public:
    int minScore(int n, std::vector<std::vector<int>>& roads) {
        std::vector<std::vector<std::pair<int, int>>> adj(n + 1);
        for (const auto& r : roads) {
            adj[r[0]].push_back({r[1], r[2]});
            adj[r[1]].push_back({r[0], r[2]});
        }
        std::vector<bool> visited(n + 1, false);
        visited[1] = true;
        std::queue<int> q;
        q.push(1);
        int min_weight = 1e9;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (const auto& [v, w] : adj[u]) {
                min_weight = std::min(min_weight, w);
                if (!visited[v]) {
                    visited[v] = true;
                    q.push(v);
                }
            }
        }
        return min_weight;
    }
};

class Solution {
    public int minScore(int n, int[][] roads) {
        java.util.List<int[]>[] adj = new java.util.ArrayList[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new java.util.ArrayList<>();
        for (int[] r : roads) {
            adj[r[0]].add(new int[]{r[1], r[2]});
            adj[r[1]].add(new int[]{r[0], r[2]});
        }
        boolean[] visited = new boolean[n + 1];
        visited[1] = true;
        java.util.Queue<Integer> q = new java.util.LinkedList<>();
        q.offer(1);
        int minWeight = Integer.MAX_VALUE;
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int[] edge : adj[u]) {
                minWeight = Math.min(minWeight, edge[1]);
                if (!visited[edge[0]]) {
                    visited[edge[0]] = true;
                    q.offer(edge[0]);
                }
            }
        }
        return minWeight;
    }
}

var minScore = function(n, roads) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v, w] of roads) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const visited = new Set([1]);
    const q = [1];
    let minWeight = Infinity;
    while (q.length > 0) {
        const u = q.shift();
        for (const [v, w] of adj[u]) {
            minWeight = Math.min(minWeight, w);
            if (!visited.has(v)) {
                visited.add(v);
                q.push(v);
            }
        }
    }
    return minWeight;
};
